class AgentBridge:
    "A kernel-based control surface for an agent, allowing reading the token from the namespace. Joining the kernel equates to joining the agent; no second security check exists."
    FIELDS = ('model', 'input', 'output', 'total', 'cached', 'cache_write', 'reasoning', 'cost', 'turns')

    def __init__(self, agent, dispatch=None):
        self.agent, self.token = agent, os.urandom(24).hex()
        self.server = self.thread = None
        self.lock = threading.Lock()
        self.dispatch = dispatch

    @classmethod
    def _usage(cls, usage):
        return {k: getattr(usage, k, None) for k in cls.FIELDS}

    def call(self, op, name=None):
        with self.lock:
            if op == 'usage': return self._usage(self.agent.use)
            if op == 'turn_usage': return self._usage(self.agent.turn_use)
            if op == 'chat_usage':
                chat = self.agent.chat_or_none('turn')
                return None if chat is None else self._usage(chat.use)
            if op == 'callbacks':
                from .runtime import CHAT_CALLBACKS
                return {'known': sorted(CHAT_CALLBACKS),
                        'attached': sorted(getattr(self.agent, '_chat_callbacks', {}) or {})}
            if op == 'attach_callback':
                if not name: raise ValueError('attach_callback needs the name of a callback')
                return self._as_owner(lambda: self.agent.chat_callback(name))
            raise ValueError(f'unknown agent operation {op!r}')

    def _as_owner(self, work):
        "Executes a mutation in the agent's environment and returns its output. Reading counters is safe; attaching callbacks can build backends and access ongoing chats. `dispatch` runs on its own thread; otherwise, on the owner's thread."
        return work() if self.dispatch is None else self.dispatch(work)

    async def start(self):
        from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
        bridge = self
        class Handler(BaseHTTPRequestHandler):
            def do_GET(self):
                parsed = urllib.parse.urlparse(self.path)
                if parsed.path != '/agent': return self._reply(404, {'error': 'no such path'})
                if not hmac.compare_digest(self.headers.get('Authorization') or '',
                                          f'Bearer {bridge.token}'):
                    return self._reply(401, {'error': 'that is not this bridge\'s token'})
                query = urllib.parse.parse_qs(parsed.query)
                try: body, status = {'result': bridge.call(query.get('op', [''])[0],
                                                           query.get('name', [None])[0])}, 200
                except Exception as e: body, status = {'error': f'{type(e).__name__}: {e}'}, 400
                self._reply(status, body)
            def _reply(self, status, body):
                data = json.dumps(body).encode()
                self.send_response(status)
                self.send_header('Content-Type', 'application/json')
                self.send_header('Content-Length', str(len(data)))
                self.end_headers(); self.wfile.write(data)
            def log_message(self, *args): pass
        self.server = ThreadingHTTPServer(('127.0.0.1', 0), Handler)
        self.thread = threading.Thread(target=self.server.serve_forever, daemon=True)
        self.thread.start()
        return f'http://127.0.0.1:{self.server.server_port}'

    async def close(self):
        "Closing an unstarted or half-started bridge is not an error."
        if self.server is None: return
        self.server.shutdown()
        if self.thread is not None: self.thread.join()
        self.server.server_close()
        self.server = self.thread = None

#: The proxy's own source, with nothing substituted into it. Defined once and rebound per agent,
#: so binding a second session's agent in the same namespace does not redefine the class.
PROXY_CLASS = """import json as _json, urllib.parse as _parse, urllib.request as _req

class AgentProxy:
    "One ramabana agent, reached over the loopback bridge its session opened."
    def __init__(self, url, token, label): self.url, self.token, self.label = url, token, label
    def __repr__(self): return 'AgentProxy(' + repr(self.label) + ')'
    def _call(self, op, name=None):
        args = {'op': op}
        if name: args['name'] = name
        req = _req.Request(self.url + '/agent?' + _parse.urlencode(args), headers={'Authorization': 'Bearer ' + self.token})
        try:
            with _req.urlopen(req) as resp: body = _json.load(resp)
        except _req.HTTPError as e:
            try: raise RuntimeError(_json.load(e).get('error') or str(e)) from None
            except ValueError: raise RuntimeError(str(e)) from None
        if 'error' in body: raise RuntimeError(body['error'])
        return body['result']
    def usage(self): return self._call('usage')
    def turn_usage(self): return self._call('turn_usage')
    def chat_usage(self): return self._call('chat_usage')
    def callbacks(self): return self._call('callbacks')
    def attach_callback(self, name): return self._call('attach_callback', name)
"""

def agent_proxy_code(url, token, label='local'):
    "The source binding an agent's proxy for its namespace. `ramabana_agent` is the last bound session; `ramabana_agents` stores all by label for shared kernels."
    return PROXY_CLASS + (
        '\ntry: ramabana_agents\nexcept NameError: ramabana_agents = {}\n'
        f'ramabana_agent = AgentProxy({url!r}, {token!r}, {label!r})\n'
        f'ramabana_agents[{label!r}] = ramabana_agent\n')

def inject_agent_proxy(host, url, token, label='local'):
    "Binds the agent proxy in Dhrishti's overlay for each session's namespace, including the prompt namespace via `agent_proxy_code`."
    return host.run_python(agent_proxy_code(url, token, label))

